function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1e6)) return 'Each value in nums is an integer from 0 to 10^6.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is an integer from 1 to nums.length.';
  return null;
}

