  const n = nums.length;
  const diff = new Array(n + 1).fill(0);
  let active = 0;
  for (let i = 0; i < n; i++) {
    active += diff[i];
    const remaining = nums[i] - active;
    if (remaining < 0) {
      return false;
    }
    if (remaining > 0) {
      if (i + k > n) {
        return false;
      }
      active += remaining;
      diff[i + k] -= remaining;
    }
  }
  return true;
}

