function checkArray(nums, k) {
  // Repeatedly clear the leftmost non-zero element with the only block that can still reach it.
  const values = nums.slice();
  for (let start = 0; start + k <= values.length; start++) {
    const times = values[start];
    for (let j = start; j < start + k; j++) {
      values[j] -= times;
      if (values[j] < 0) return false;
    }
  }
  return values.every(v => v === 0);
}

