function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const k = 1 + Math.floor(rand() * (large && rand() < 0.5 ? Math.min(n, 50) : n));
  // Build a solvable array from random operation counts per block start.
  const most = large ? Math.min(1000, Math.floor(1e6 / k)) : 3;
  const nums = new Array(n).fill(0);
  for (let start = 0; start + k <= n; start++) {
    const times = Math.floor(rand() * (most + 1));
    for (let j = start; j < start + k; j++) nums[j] += times;
  }
  // About half the time nudge one value so the answer is usually false.
  if (rand() < 0.5) {
    const index = Math.floor(rand() * n);
    if (nums[index] > 0 && (rand() < 0.5 || nums[index] === 1e6)) nums[index] -= 1;
    else nums[index] += 1;
  }
  return [nums, k];
}
